import json
from pathlib import Path
R=Path('D:/Codex/sd-research');out=[]
def model(id):
 global mid,d
 mid=id;d=json.loads((R/'data/parts'/f'{id}.json').read_text())
def add(g,cs,label,family,material,location,notes='',confidence='high'):
 if isinstance(cs,int):cs=[cs]
 for c in cs:
  p=next(p for p in d['parts']if p['geoset1']==g and p['component1']==c)
  out.append(dict(modelId=mid,modelPath=d['logicalPath'],partId=p['id'],geoset1=g,component1=c,label=label,family=family,material=material,location=location,confidence=confidence,evidence='Agent vision review: two isolated textured angles and full-model placement; physical component boundaries checked against measured faces',capture=f'captures/models/{mid}/index.html',notes=notes))
